function unwrapApi(data,key){if(data?.success===false){if(String(data.message||'').includes('Sesi tidak valid')){sessionStorage.removeItem(AUTH_TOKEN_KEY);showPinGate(data.message);}throw new Error(data.message||'Permintaan API gagal.');}return data?.[key]??data?.data?.[key]??data?.data??data;}
async function apiGet(action){const response=await fetch(`${API_URL}?action=${encodeURIComponent(action)}&token=${encodeURIComponent(authToken())}&t=${Date.now()}`,{method:'GET',redirect:'follow'});if(!response.ok)throw new Error(`API ${response.status}`);const data=await response.json();if(data?.success===false)unwrapApi(data);return data;}
async function apiPost(action,payload){const response=await fetch(`${API_URL}?action=${encodeURIComponent(action)}`,{method:'POST',redirect:'follow',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({...payload,token:authToken()})});if(!response.ok)throw new Error(`API ${response.status}`);const data=await response.json();if(data?.success===false)unwrapApi(data);return data;}
async function authenticate(pin){const response=await fetch(`${API_URL}?action=authenticate`,{method:'POST',redirect:'follow',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({pin})});if(!response.ok)throw new Error(`API ${response.status}`);return response.json();}
