function productActiveValue(value){const text=String(value??'').trim().toLowerCase();if(!text)return 1;if(text.includes('non')||text==='0'||text==='false')return 0;return 1;}
function normalizeProduct(p,i=0){return{id:p.id??p.ID??p.SKU??p.sku??i+1,sku:String(p.sku??p.SKU??''),name:String(p.name??p['Nama Produk']??p.Nama??''),category:String(p.category??p.Kategori??''),brand:String(p.brand??p.Brand??'Tanpa Brand'),cost:clean(p.cost??p['Harga Modal']),price:clean(p.price??p['Harga Jual']??p.Harga),stock:clean(p.stock??p.Stok),active:productActiveValue(p.active??p.Aktif??p.Status),updated_at:p.updated_at??p['Updated At']??''};}
