function normalizeOrder(o,i=0){return{...o,id:o.id??o.orderId??o['Order ID']??i+1,order_number:o.order_number??o.orderId??o['Order ID']??'-',created_at:o.created_at??o.Tanggal??'',receiver_name:o.receiver_name??o['Nama Customer']??'',receiver_phone:o.receiver_phone??o['No WhatsApp']??'',receiver_address:o.receiver_address??o.Alamat??'',courier:o.courier??o.Ekspedisi??'',shipping:clean(o.shipping??o.Ongkir),discount:clean(o.discount??o.Diskon),subtotal:clean(o.subtotal??o.Subtotal),total:clean(o.total??o.totalOrder??o['Total Order']??o.Total),notes:o.notes??o.Catatan??'',items:o.items||[]};}
function applySnapshot(data){products=(Array.isArray(data.products)?data.products:[]).map(normalizeProduct);orders=(Array.isArray(data.orders)?data.orders:[]).map(normalizeOrder);stockMutations=Array.isArray(data.mutations)?data.mutations:[];customers=Array.isArray(data.customers)?data.customers:[];dashboardData=data.dashboard||{};saveData();}
async function refreshSnapshot(repair=false){const data=repair?unwrapApi(await apiPost('repairData',{}),'snapshot'):unwrapApi(await apiGet('getSnapshot'));applySnapshot(data);renderAll();renderMarketplaceProductOptions();renderBonusOptions();renderBonusCart();renderDatabase();setApiStatus('Seluruh data tersinkron dengan Google Sheets.','success');return data;}
async function loadData(){const localProducts=storedProducts();const localOrders=JSON.parse(localStorage.getItem('cm_orders')||'[]');if(!onlineEnabled()){products=localProducts;orders=localOrders;saveData();return;}let data=unwrapApi(await apiPost('repairData',{}),'snapshot');if(!Array.isArray(data.products)||!data.products.length){setApiStatus('Menyiapkan produk awal di Google Sheets...','warning');await apiPost('seedProducts',{items:SEED_PRODUCTS});data=unwrapApi(await apiPost('repairData',{}),'snapshot');}applySnapshot(data);}
