function setApiStatus(message,type=''){if(el('apiStatus')){el('apiStatus').textContent=message;el('apiStatus').className=`api-status ${type}`;}}
function splitCSV(line){const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(q&&line[i+1]==='"'){cur+='"';i++;}else q=!q;}else if((ch===','||ch===';')&&!q){out.push(cur);cur='';}else cur+=ch;}out.push(cur);return out;}

function colToIndex(col){let n=0;for(let i=0;i<col.length;i++)n=n*26+(col.charCodeAt(i)-64);return n-1;}
async function inflateRaw(data){
  if('DecompressionStream' in window){
    const ds=new DecompressionStream('deflate-raw');
    const stream=new Blob([data]).stream().pipeThrough(ds);
    const buf=await new Response(stream).arrayBuffer();
    return new Uint8Array(buf);
  }
  throw new Error('Browser tidak mendukung import Excel .xlsx. Gunakan Chrome/Edge terbaru.');
}
function u16(a,o){return a[o]|(a[o+1]<<8)}
function u32(a,o){return (a[o]|(a[o+1]<<8)|(a[o+2]<<16)|(a[o+3]<<24))>>>0}
async function unzipXlsx(buf){
  const a=new Uint8Array(buf), files={};
  let eocd=-1;
  for(let i=a.length-22;i>=0;i--){if(a[i]===0x50&&a[i+1]===0x4b&&a[i+2]===0x05&&a[i+3]===0x06){eocd=i;break;}}
  if(eocd<0)throw new Error('File Excel tidak valid.');
  let total=u16(a,eocd+10), cdOffset=u32(a,eocd+16), p=cdOffset;
  for(let n=0;n<total;n++){
    if(!(a[p]===0x50&&a[p+1]===0x4b&&a[p+2]===0x01&&a[p+3]===0x02))break;
    const method=u16(a,p+10), csize=u32(a,p+20), nlen=u16(a,p+28), elen=u16(a,p+30), clen=u16(a,p+32), lhoff=u32(a,p+42);
    const name=new TextDecoder().decode(a.slice(p+46,p+46+nlen));
    const lnlen=u16(a,lhoff+26), lelen=u16(a,lhoff+28);
    const start=lhoff+30+lnlen+lelen;
    const comp=a.slice(start,start+csize);
    let data=comp;
    if(method===8)data=await inflateRaw(comp);
    else if(method!==0)throw new Error('Metode kompresi Excel tidak didukung.');
    files[name]=new TextDecoder().decode(data);
    p+=46+nlen+elen+clen;
  }
  return files;
}
function xmlDecode(s){return String(s||'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'");}
async function parseXLSX(file){
  const files=await unzipXlsx(await file.arrayBuffer());
  const sharedXml=files['xl/sharedStrings.xml']||'';
  const shared=[...sharedXml.matchAll(/<si[\s\S]*?<\/si>/g)].map(m=>xmlDecode([...m[0].matchAll(/<t[^>]*>([\s\S]*?)<\/t>/g)].map(x=>x[1]).join('')));
  let sheetPath='xl/worksheets/sheet1.xml';
  const wb=files['xl/workbook.xml']||'', rels=files['xl/_rels/workbook.xml.rels']||'';
  const sm=/<sheet[^>]*r:id="([^"]+)"/.exec(wb);
  if(sm){
    const rm=new RegExp('<Relationship[^>]*Id="'+sm[1]+'"[^>]*Target="([^"]+)"').exec(rels);
    if(rm)sheetPath='xl/'+rm[1].replace(/^\/?xl\//,'');
  }
  const sheet=files[sheetPath];
  if(!sheet)throw new Error('Sheet produk tidak ditemukan.');
  const rows=[];
  for(const rm of sheet.matchAll(/<row[^>]*>([\s\S]*?)<\/row>/g)){
    const arr=[];
    for(const cm of rm[1].matchAll(/<c[^>]*r="([A-Z]+)\d+"([^>]*)>([\s\S]*?)<\/c>/g)){
      const idx=colToIndex(cm[1]), attr=cm[2], inner=cm[3];
      let val='';
      const vm=/<v>([\s\S]*?)<\/v>/.exec(inner);
      if(attr.includes('t="inlineStr"')){
        val=xmlDecode([...inner.matchAll(/<t[^>]*>([\s\S]*?)<\/t>/g)].map(x=>x[1]).join(''));
      }else if(vm){
        val=vm[1];
        if(attr.includes('t="s"'))val=shared[Number(val)]||'';
      }
      arr[idx]=val;
    }
    rows.push(arr);
  }
  if(rows.length<2)return[];
  const headers=rows[0].map(x=>String(x||'').toLowerCase().trim());
  const find=(names)=>{for(const name of names){const i=headers.findIndex(h=>h.includes(name));if(i>=0)return i;}return -1;};
  const skuI=find(['sku','kode','code']);
  const nameI=find(['nama produk','produk','nama','name','product']);
  const catI=find(['kategori','category','jenis']);
  const brandI=find(['brand','merek']);
  const costI=find(['harga modal','modal','cost']);
  const priceI=find(['harga jual','harga','price']);
  const statusI=find(['status','active']);
  return rows.slice(1).map((r,i)=>({
    sku:String(r[skuI]||`AUTO-${Date.now()}-${i}`).trim(),
    name:String(r[nameI]||'').trim(),
    category:String(r[catI]||'').trim(),
    brand:String(r[brandI]||'Tanpa Brand').trim(),
    cost:clean(r[costI]),
    price:clean(r[priceI]),
    active:String(r[statusI]||'Aktif').toLowerCase().includes('non')?0:1,
    updated_at:new Date().toLocaleString('id-ID')
  })).filter(p=>p.name);
}
function exportExcel(name, rows, headers){
  const headerRow=headers.map(h=>`<th>${esc(h.label)}</th>`).join('');
  const body=rows.map(r=>`<tr>${headers.map(h=>`<td>${esc(typeof h.value==='function'?h.value(r):r[h.key])}</td>`).join('')}</tr>`).join('');
  const html=`<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"></head><body><table border="1"><thead><tr>${headerRow}</tr></thead><tbody>${body}</tbody></table></body></html>`;
  download(name, html, 'application/vnd.ms-excel');
}
function parseCSV(t){const lines=t.replace(/^\uFEFF/,'').replace(/\r/g,'').split('\n').filter(x=>x.trim());if(lines.length<2)return[];const h=splitCSV(lines[0]).map(x=>x.trim().toLowerCase());return lines.slice(1).map((line,i)=>{const cols=splitCSV(line),r={};h.forEach((x,j)=>r[x]=(cols[j]||'').trim());return{sku:r.kode||r.sku||r.code||`AUTO-${Date.now()}-${i}`,name:r.nama||r.produk||r['nama produk']||r.name||'',category:r.kategori||r.category||'',brand:r.brand||r.merek||'Tanpa Brand',cost:clean(r.modal||r.cost||r['harga modal']),price:clean(r.harga||r.price||r['harga jual']),active:String(r.status||r.active||'1').toLowerCase().includes('non')?0:1,updated_at:new Date().toLocaleString('id-ID')};}).filter(p=>p.name);}
async function importProducts(items){if(onlineEnabled()){await apiPost('upsertProducts',{items});await refreshSnapshot();return;}const map=new Map(products.map(p=>[String(p.sku),p]));items.forEach(p=>{p.sku=String(p.sku||`AUTO-${Date.now()}`).trim();p.name=String(p.name||'').trim();p.category=String(p.category||'').trim();p.brand=String(p.brand||'Tanpa Brand').trim();p.cost=clean(p.cost);p.price=clean(p.price);p.active=Number(p.active??1);p.updated_at=new Date().toLocaleString('id-ID');if(map.has(p.sku))Object.assign(map.get(p.sku),p);else{p.id=Date.now()+Math.floor(Math.random()*999999);map.set(p.sku,p);}});products=[...map.values()];saveData();renderAll();}
function filteredProducts(q=''){const s=q.toLowerCase();return products.filter(p=>p.active!==0&&(!s||String(p.name).toLowerCase().includes(s)||String(p.sku).toLowerCase().includes(s)||String(p.category).toLowerCase().includes(s))).slice(0,150);}
