function productCodePart(value,fallback){const part=String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toUpperCase().slice(0,3);return part||fallback;}
function generateProductSku(){if(el('productId').value)return el('formSku').value;const prefix=`${productCodePart(el('formCategory').value,'PRD')}-${productCodePart(el('formBrand').value,'GEN')}`,used=new Set(products.map(p=>String(p.sku).toUpperCase()));let number=1,sku='';do{sku=`${prefix}-${String(number++).padStart(3,'0')}`;}while(used.has(sku));el('formSku').value=sku;return sku;}
function renderProductFormOptions(){const categories=[...new Set(products.map(p=>p.category).filter(Boolean))].sort(),brands=[...new Set(products.map(p=>p.brand).filter(b=>b&&b!=='Tanpa Brand'))].sort();el('productCategoryOptions').innerHTML=categories.map(value=>`<option value="${esc(value)}"></option>`).join('');el('productBrandOptions').innerHTML=brands.map(value=>`<option value="${esc(value)}"></option>`).join('');if(!el('productId').value)generateProductSku();}
function renderProducts(){const list=filteredProducts(el('searchInput').value||'');el('productCount').textContent=`${products.filter(p=>p.active!==0).length} produk aktif`;el('productList').innerHTML=list.map(p=>`<div class="product-item" data-id="${p.id}"><div class="product-name">${esc(p.name)}</div><div class="product-meta"><span>${esc(p.sku||'-')} · ${esc(p.category||'-')}</span><strong>${rupiah(p.price)}</strong></div><button class="product-add-btn" type="button">+ Tambah Produk</button></div>`).join('')||`<div class="empty" style="min-height:120px;display:flex">Produk tidak ditemukan.</div>`;}
function renderMasterProducts(){const q=(el('masterSearch')?.value||'').toLowerCase();const list=products.filter(p=>!q||String(p.name).toLowerCase().includes(q)||String(p.sku).toLowerCase().includes(q)||String(p.category).toLowerCase().includes(q)||String(p.brand).toLowerCase().includes(q));el('masterProductRows').innerHTML=list.map(p=>`<tr><td>${esc(p.sku)}</td><td>${esc(p.name)}<br><small>${esc(p.brand||'Tanpa Brand')}</small></td><td>${esc(p.category)}</td><td>${rupiah(p.price||0)}</td><td><strong>${clean(p.stock)}</strong></td><td><span class="${p.active!==0?'status-on':'status-off'}">${p.active!==0?'Aktif':'Nonaktif'}</span></td><td><div class="row-actions"><button data-edit-product="${p.id}">Edit</button><button data-add-stock="${p.id}" class="secondary">+ Stok</button><button data-toggle-product="${p.id}" class="ghost">${p.active!==0?'Nonaktif':'Aktifkan'}</button></div></td></tr>`).join('')||`<tr><td colspan="7">Produk tidak ditemukan.</td></tr>`;renderProductFormOptions();}
function updateStats(){const d=dashboardData||{},now=new Date(),monthly=orders.reduce((result,o)=>{const date=sheetDate(o.created_at);if(date&&date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth()){result.revenue+=clean(o.total);result.shipping+=clean(o.shipping);}return result;},{revenue:0,shipping:0}),productAssets=products.reduce((sum,p)=>sum+Math.max(0,clean(p.stock))*clean(p.price),0),lowStock=Array.isArray(d.stokMenipis)?d.stokMenipis.length:d.stokMenipis,monthName=new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric'}).format(now);el('statProducts').textContent=d.totalProduk??products.length;el('statActive').textContent=d.produkAktif??products.filter(p=>p.active!==0).length;el('statStock').textContent=d.totalStok??products.reduce((s,p)=>s+clean(p.stock),0);el('statOrdersToday').textContent=d.orderHariIni??0;el('statRevenueToday').textContent=rupiah(d.omzetHariIni??0);el('statRevenueMonth').textContent=rupiah(d.omzetBulanIni??monthly.revenue);el('statShippingMonth').textContent=rupiah(d.ongkirBulanIni??monthly.shipping);el('statProductAssets').textContent=rupiah(d.nilaiAsetProduk??productAssets);el('statRevenue').textContent=rupiah(d.omzetTotal??orders.reduce((s,o)=>s+clean(o.total),0));el('statLowStock').textContent=lowStock??products.filter(p=>p.active!==0&&clean(p.stock)<=5).length;el('dashboardPeriod').textContent=`Ringkasan penjualan ${new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now)}`;el('revenueMonthLabel').textContent=`Total penjualan ${monthName}`;el('shippingMonthLabel').textContent=`Total ongkir ${monthName}`;}
function addToCart(p){const ex=cart.find(x=>x.id===p.id);if(ex)ex.qty++;else cart.push({...p,qty:1});renderCart();}
function totals(){const subtotal=cart.reduce((s,i)=>s+i.price*i.qty,0),shipping=clean(el('shipping').value),discount=clean(el('discount').value);return{subtotal,shipping,discount,total:Math.max(0,subtotal+shipping-discount)};}
function renderCart(){if(!cart.length){el('cartList').className='cart-list empty';el('cartList').style.display='flex';el('cartList').innerHTML='Belum ada produk.';}else{el('cartList').className='cart-list';el('cartList').innerHTML=cart.map((i,n)=>`<div class="cart-item"><div><div class="cart-line-title">${esc(i.name)}</div><div class="cart-line-sub">${esc(i.sku||'-')} · ${rupiah(i.price)} × ${i.qty}</div></div><input class="qty-input" type="number" min="1" value="${i.qty}" data-idx="${n}"><button class="icon-btn" data-del="${n}">×</button></div>`).join('');}updateAll();}
