el('marketplaceCategory').addEventListener('change',()=>{el('marketplaceBrand').value='';renderMarketplaceBrands();});el('marketplaceBrand').addEventListener('change',renderMarketplaceProductChoices);el('addMarketplaceChoiceBtn').onclick=()=>{const id=el('marketplaceProductChoice').value;if(!id)return alert('Pilih produk terlebih dahulu.');addMarketplaceProduct(id);};el('marketplaceProductSearch').addEventListener('input',renderMarketplaceSearch);el('marketplaceCart').addEventListener('input',e=>{if(e.target.matches('[data-marketplace-qty]')){const item=marketplaceCart[Number(e.target.dataset.marketplaceQty)];item.qty=Math.min(clean(item.stock),Math.max(1,Number(e.target.value)||1));renderMarketplaceCart();}});el('marketplaceOrderForm').addEventListener('submit',saveMarketplaceOrder);el('resetMarketplaceBtn').onclick=resetMarketplace;
el('bonusCategory').addEventListener('change',()=>{el('bonusBrand').value='';renderBonusBrands();});el('bonusBrand').addEventListener('change',renderBonusProducts);el('addBonusChoiceBtn').onclick=()=>{const id=el('bonusProduct').value;if(!id)return alert('Pilih produk terlebih dahulu.');addBonusProduct(id);};el('bonusProductSearch').addEventListener('input',renderBonusSearch);el('bonusCart').addEventListener('input',e=>{if(e.target.matches('[data-bonus-cart-qty]')){const item=bonusCart[Number(e.target.dataset.bonusCartQty)];item.qty=Math.min(clean(item.stock),Math.max(1,Number(e.target.value)||1));renderBonusCart();}});el('bonusForm').addEventListener('submit',saveBonus);el('resetBonusBtn').onclick=resetBonus;
async function initializeApp(){renderCart();renderMarketplaceCart();renderMarketplaceProductOptions();renderBonusCart();renderBonusOptions();renderDatabase();showTab('dashboard');try{await loadData();}catch(err){console.error(err);if(onlineEnabled()){products=[];orders=[];stockMutations=[];customers=[];dashboardData={};setApiStatus(`Sinkronisasi Google Sheets gagal: ${err.message}`,'error');}else{products=storedProducts();orders=JSON.parse(localStorage.getItem('cm_orders')||'[]');setApiStatus('Mode lokal aktif.','warning');}}renderAll();renderMarketplaceProductOptions();renderBonusOptions();renderBonusCart();}
async function bootstrap(){if(!authToken())return showPinGate();try{unwrapApi(await apiGet('checkAuth'));showApp();await initializeApp();}catch(err){sessionStorage.removeItem(AUTH_TOKEN_KEY);showPinGate(err.message);}}
bootstrap();
